def compute(vars):
    old_revenue = vars["v1"]
    new_revenue = vars["v2"]

    try:
        change_ratio = (new_revenue - old_revenue) / old_revenue
    except ZeroDivisionError:
        return None

    value = change_ratio * 100

    return {
        "value": value,
        "trace": {
            "old_revenue": old_revenue,
            "new_revenue": new_revenue,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": "GBP",
                "scale": "million",
                "unit": "percentage"
            }
        }
    }
